// Quantum Algorithms (700줄)
// Shor, Grover, VQE, 임의의 미분 가능 회로

struct AlgorithmResult {
    algorithm_name: string,
    success: bool,
    result_value: i32,
    iterations: i32,
    probability: f64,
    accuracy: f64,
