// BB84 Quantum Key Distribution
fn initialize_bb84_exchange(key_length: i32) -> BB84KeyExchange {
    return BB84KeyExchange{
        alice_bits: generate_random_bits(key_length),
        alice_bases: generate_random_bases(key_length),
        bob_bases: generate_random_bases(key_length),
        bob_measurements: array(),
        sift_key: array(),
        key_length: key_length,
        qber: 0.0,
        secure: false,
    };
}

fn generate_random_bits(count: i32) -> any {
    let bits = array();
    let i = 0;
    while i < count {
        let bit = if random_f64() > 0.5 { 1 } else { 0 };
        push(bits, bit);
        i = i + 1;
    }
    return bits;
}

fn generate_random_bases(count: i32) -> any {
    let bases = array();
    let i = 0;
    while i < count {
        let base = if random_f64() > 0.5 { 1 } else { 0 };
        push(bases, base);
        i = i + 1;
    }
    return bases;
}

fn alice_send_bb84_qubits(exchange: BB84KeyExchange) -> any {
    // Alice prepares qubits according to bits and bases
    let qubits = array();

    let i = 0;
    while i < length(exchange.alice_bits) {
        let bit = at(exchange.alice_bits, i);
        let base = at(exchange.alice_bases, i);

        // Prepare qubit in (bit, base)
        let qbit = create_prepared_qubit(bit, base);
        push(qubits, qbit);

        i = i + 1;
    }

    return qubits;
}

fn create_prepared_qubit(bit: i32, base: i32) -> any {
    // base 0 (rectilinear): |0⟩ or |1⟩
    // base 1 (diagonal): |+⟩ or |-⟩

    if base == 0 {
        if bit == 0 {
            return dict_create("alpha", 1.0, "beta", 0.0);  // |0⟩
        } else {
            return dict_create("alpha", 0.0, "beta", 1.0);  // |1⟩
        }
    } else {
        if bit == 0 {
            return dict_create("alpha", 0.707, "beta", 0.707);   // |+⟩
        } else {
            return dict_create("alpha", 0.707, "beta", -0.707);  // |-⟩
        }
    }
}

fn bob_measure_bb84_qubits(exchange: BB84KeyExchange, qubits: any) -> BB84KeyExchange {
    // Bob measures qubits using random bases
    let measurements = array();

    let i = 0;
    while i < length(qubits) {
        let qbit = at(qubits, i);
        let bob_base = at(exchange.bob_bases, i);

        // Measure in bob_base
        let measurement = measure_in_basis(qbit, bob_base);
        push(measurements, measurement);

        i = i + 1;
    }

    exchange.bob_measurements = measurements;
    return exchange;
}

fn measure_in_basis(qbit: any, base: i32) -> i32 {
    // Measure qubit in specified basis
    let alpha = dict_get_f64(qbit, "alpha");
    let beta = dict_get_f64(qbit, "beta");

    let prob_0 = alpha * alpha;
    if random_f64() < prob_0 {
        return 0;
    } else {
        return 1;
    }
}

fn sift_bb84_key(exchange: BB84KeyExchange) -> BB84KeyExchange {
    // Keep only measurements where Alice and Bob used same basis
    let sift_key = array();

    let i = 0;
    while i < length(exchange.alice_bits) {
        let alice_base = at(exchange.alice_bases, i);
        let bob_base = at(exchange.bob_bases, i);

        if alice_base == bob_base {
            let bit = at(exchange.alice_bits, i);
            push(sift_key, bit);
        }

        i = i + 1;
    }

    exchange.sift_key = sift_key;
    exchange.key_length = length(sift_key);
    return exchange;
}

fn check_bb84_eavesdropping(exchange: BB84KeyExchange) -> f64 {
    // Calculate QBER (Quantum Bit Error Rate)
    // QBER > 11% indicates eavesdropping

    let errors = 0;
    let same_basis_count = 0;

    let i = 0;
    while i < length(exchange.alice_bits) {
        let alice_base = at(exchange.alice_bases, i);
        let bob_base = at(exchange.bob_bases, i);

        if alice_base == bob_base {
            let alice_bit = at(exchange.alice_bits, i);
            let bob_bit = at(exchange.bob_measurements, i);

            if alice_bit != bob_bit {
                errors = errors + 1;
            }
            same_basis_count = same_basis_count + 1;
        }

        i = i + 1;
    }

    if same_basis_count == 0 {
        return 0.0;
    }

    let qber = to_f64(errors) / to_f64(same_basis_count);
    exchange.qber = qber;
    exchange.secure = qber < 0.11;  // Threshold: 11%

    return qber;
}

// Quantum Teleportation (3-qubit protocol)
fn quantum_teleportation_encode(message_qbit: any, bell_pair: any) -> any {
    // Bell state measurement on message + half of entangled pair
    let alice_qbit = message_qbit;
    let entangled_qbit = at(bell_pair, 0);

    // CNOT(alice, entangled)
    let cnot_result = apply_cnot_encoding(alice_qbit, entangled_qbit);

    // Hadamard on alice
    let h_result = apply_hadamard_encoding(alice_qbit);

    // Measure both qubits -> 2 classical bits
    let bit1 = measure_qubit_outcome(alice_qbit);
    let bit2 = measure_qubit_outcome(entangled_qbit);

    return dict_create("c1", bit1, "c2", bit2);
}

