// Super Dense Coding (1 qubit carries 2 classical bits)
fn super_dense_coding_encode(message: any) -> SuperDenseCoding {
    // Alice and Bob share entangled pair (Bell state |Φ+⟩)
    // Alice encodes 2-bit message with single-qubit gate

    let bit0 = at(message, 0);
    let bit1 = at(message, 1);

    let gate_to_apply = bit0 * 2 + bit1;  // 0=I, 1=X, 2=Y, 3=Z

    return SuperDenseCoding{
        message_bits: message,
        encoded_state: gate_to_apply,
        bell_basis_measurement: 0,
        decoded_bits: array(),
        success: true,
    };
}

fn super_dense_coding_decode(encoding: SuperDenseCoding) -> SuperDenseCoding {
    // Bob measures in Bell basis
    // 4 different Bell states encode 4 possibilities (00, 01, 10, 11)

    let gate_applied = encoding.encoded_state;

    let decoded = array();
    push(decoded, gate_applied / 2);  // bit0
    push(decoded, gate_applied % 2);  // bit1

    encoding.decoded_bits = decoded;
    encoding.success = true;

    return encoding;
}

// Quantum Channel Management
fn create_quantum_channel(id: i32, distance: f64) -> QuantumChannel {
    // Attenuation: loss_rate increases with distance
    let loss_rate = 1.0 - exp(-distance / 20.0);  // 20 km scale

    return QuantumChannel{
        channel_id: id,
        loss_rate: loss_rate,
        noise_rate: 0.01,    // 1% depolarizing noise
        bandwidth: 1000,     // 1000 qubits/sec
        distance: distance,
        fidelity: 1.0 - loss_rate,
        status: "active",
    };
}

fn transmit_through_quantum_channel(channel: QuantumChannel, qubits: any) -> any {
    let transmitted_qubits = array();

    let i = 0;
    while i < length(qubits) {
        let qbit = at(qubits, i);

        // Apply loss with probability loss_rate
        if random_f64() > channel.loss_rate {
            // Apply noise
            qbit = apply_quantum_noise(qbit, channel.noise_rate);
            push(transmitted_qubits, qbit);
        }

        i = i + 1;
    }

    return transmitted_qubits;
}

fn apply_quantum_noise(qbit: any, noise_rate: f64) -> any {
    // Depolarizing channel: with prob noise_rate, apply random Pauli
    if random_f64() < noise_rate {
        let pauli_type = random_int(3);
        if pauli_type == 0 {
            qbit = apply_pauli_x_correction(qbit);
        } else if pauli_type == 1 {
            qbit = apply_pauli_z_correction(qbit);
        }
    }

    return qbit;
}

fn channel_hop_quantum_signal(source_channel: QuantumChannel, dest_channel: QuantumChannel, qubits: any) -> any {
    // Entanglement swapping across channels
    let result = transmit_through_quantum_channel(source_channel, qubits);
    result = transmit_through_quantum_channel(dest_channel, result);

    return result;
}

