// Initialize Quantum Network
fn create_quantum_network() -> QuantumNetworkState {
    return QuantumNetworkState{
        nodes: array(),
        links: array(),
        routing_table: dict(),
        entanglement_distribution_queue: array(),
        timestamp: 0.0,
        network_fidelity: 1.0,
    };
}

fn add_quantum_node(network: QuantumNetworkState, node_id: i32, x: f64, y: f64) -> QuantumNetworkState {
    let node = QuantumNode{
        node_id: node_id,
        position: dict_create_pos("x", x, "y", y),
        qubits_available: 100,
        connected_nodes: array(),
        quantum_memory: array(),
        reputation: 1.0,
        status: "active",
    };

    push(network.nodes, node);
    return network;
}

fn add_quantum_link(network: QuantumNetworkState, source: i32, dest: i32, distance: f64) -> QuantumNetworkState {
    // Calculate fidelity based on distance
    let fidelity = calculate_link_fidelity(distance);

    let link = QuantumLink{
        link_id: length(network.links),
        source_node: source,
        dest_node: dest,
        distance: distance,
        fidelity: fidelity,
        bandwidth: 1000,
        latency: distance / 100.0,  // ~100 km/ms
        entanglement_pairs: 0,
        active: true,
    };

    push(network.links, link);

    // Update node connectivity
    let src_node = find_node(network, source);
    if src_node != null {
        push(src_node.connected_nodes, dest);
    }

    return network;
}

fn calculate_link_fidelity(distance: f64) -> f64 {
    // Fidelity decreases with distance due to loss
    // 20 km scale length
    return exp(-distance / 20.0);
}

fn find_node(network: QuantumNetworkState, node_id: i32) -> any {
    let i = 0;
    while i < length(network.nodes) {
        let node = at(network.nodes, i);
        if node.node_id == node_id {
            return node;
        }
        i = i + 1;
    }
    return null;
}

fn find_link(network: QuantumNetworkState, source: i32, dest: i32) -> any {
    let i = 0;
    while i < length(network.links) {
        let link = at(network.links, i);
        if link.source_node == source && link.dest_node == dest {
            return link;
        }
        if link.source_node == dest && link.dest_node == source {
            return link;
        }
        i = i + 1;
    }
    return null;
}

// Path Finding
fn find_quantum_path(network: QuantumNetworkState, source: i32, dest: i32) -> QuantumNetworkPath {
    // BFS to find shortest path
    let visited = dict();
    let queue = array();
    let path_dict = dict();

    push(queue, source);
    visited = dict_set(visited, source, 1);

    while length(queue) > 0 {
        let current = pop_front(queue);

        if current == dest {
            // Reconstruct path
            let path = reconstruct_path(path_dict, source, dest);
            let hops = length(path) - 1;
            let fidelity = calculate_path_fidelity(network, path);
            let distance = calculate_path_distance(network, path);

            return QuantumNetworkPath{
                path: path,
                hops: hops,
                total_distance: distance,
                path_fidelity: fidelity,
                available: fidelity > 0.5,
                priority: 0,
            };
        }

        let current_node = find_node(network, current);
        if current_node != null {
            let j = 0;
            while j < length(current_node.connected_nodes) {
                let neighbor = at(current_node.connected_nodes, j);
                if dict_get(visited, neighbor) == null {
                    visited = dict_set(visited, neighbor, 1);
                    push(queue, neighbor);
                    path_dict = dict_set(path_dict, neighbor, current);
                }
                j = j + 1;
            }
        }
    }

    // No path found
    return QuantumNetworkPath{
        path: array(),
        hops: 999,
        total_distance: 0.0,
        path_fidelity: 0.0,
        available: false,
        priority: -1,
    };
}

fn reconstruct_path(path_dict: any, source: i32, dest: i32) -> any {
    let path = array();
    let current = dest;

    while current != source {
        push(path, current);
        current = dict_get_int(path_dict, current);
    }

    push(path, source);
    return reverse_array(path);
}

fn reverse_array(arr: any) -> any {
    let reversed = array();
    let i = length(arr) - 1;

    while i >= 0 {
        push(reversed, at(arr, i));
        i = i - 1;
    }

    return reversed;
}

fn calculate_path_fidelity(network: QuantumNetworkState, path: any) -> f64 {
    // Fidelity product of all links in path
    let total_fidelity = 1.0;

    let i = 0;
    while i < length(path) - 1 {
        let source = at(path, i);
        let dest = at(path, i + 1);

        let link = find_link(network, source, dest);
        if link != null {
            total_fidelity = total_fidelity * link.fidelity;
        }

        i = i + 1;
    }

    return total_fidelity;
}

fn calculate_path_distance(network: QuantumNetworkState, path: any) -> f64 {
    // Total distance of path
    let total_distance = 0.0;

    let i = 0;
    while i < length(path) - 1 {
        let source = at(path, i);
        let dest = at(path, i + 1);

        let link = find_link(network, source, dest);
        if link != null {
            total_distance = total_distance + link.distance;
        }

        i = i + 1;
    }

    return total_distance;
}

// Entanglement Distribution
fn distribute_entanglement(network: QuantumNetworkState, source: i32, dest: i32, num_pairs: i32) -> QuantumNetworkPath {
    // Find path and distribute entanglement
    let path = find_quantum_path(network, source, dest);

    if path.available {
        // Distribute entangled pairs along path
        let i = 0;
        while i < length(path.path) - 1 {
            let node1 = at(path.path, i);
            let node2 = at(path.path, i + 1);

            let link = find_link(network, node1, node2);
            if link != null {
                link.entanglement_pairs = link.entanglement_pairs + num_pairs;
            }

            i = i + 1;
        }

        // Add to distribution queue
        let request = dict_create_dist("source", source, "dest", dest, "pairs", num_pairs);
        push(network.entanglement_distribution_queue, request);
    }

    return path;
}

