    let avg_fidelity = calculate_network_fidelity(network);

    return dict_create_stats("nodes", num_nodes, "links", num_links, "fidelity", avg_fidelity);
}

fn pop_front(queue: any) -> i32 {
    let first = at(queue, 0);
    let new_queue = array();
    let i = 1;
    while i < length(queue) {
        push(new_queue, at(queue, i));
        i = i + 1;
    }
    return first;
}

fn exp(x: f64) -> f64 {
    let result = 1.0;
    let term = 1.0;
    let i = 1;
    while i < 10 {
        term = term * x / to_f64(i);
        result = result + term;
        i = i + 1;
    }
    return result;
}

fn to_f64(x: i32) -> f64 {
    let result = 0.0;
    let i = 0;
    while i < x {
        result = result + 1.0;
        i = i + 1;
    }
    return result;
}

