fn run_test_case(test_case: any, rule: string) -> TestResult {
    let name = dict_get_str(test_case, "name");
    let expected = dict_get_f64(test_case, "expected");
    let margin = dict_get_f64(test_case, "margin");

    // Simulate test execution
    let actual = expected * (0.98 + random_f64() * 0.04);

    let passed = abs_f64(actual - expected) <= margin;

    return TestResult{
        test_name: name,
        passed: passed,
        expected: expected,
        actual: actual,
        error_margin: margin,
        rule_violated: rule,
    };
}

fn update_rule_satisfaction(suite: TestSuite, rule: string) -> TestSuite {
    // Check if all tests in this group passed
    let rule_passed = true;

    let i = length(suite.tests) - 6;
    while i < length(suite.tests) && i >= 0 {
        let test = at(suite.tests, i);
        if test.rule_violated == rule && !test.passed {
            rule_passed = false;
        }
        i = i + 1;
    }

    suite.rules_satisfied = dict_set(suite.rules_satisfied, rule, rule_passed);
    return suite;
}

fn print_test_results(suite: TestSuite) -> string {
    let result = "Test Results:\n";
    result = result + "Total: " + to_string(suite.total_tests) + "\n";
    result = result + "Passed: " + to_string(suite.passed_tests) + "\n";
    result = result + "Failed: " + to_string(suite.failed_tests) + "\n";

    return result;
}

