// Main API for Quantum Internet System
pub fn initialize_quantum_internet(num_nodes: i32, network_size: i32) -> QuantumNetworkState {
    let network = create_quantum_network();

    let i = 0;
    while i < num_nodes {
        let x = to_f64(i * 10);
        let y = to_f64((i % 5) * 20);
        network = add_quantum_node(network, i, x, y);
        i = i + 1;
    }

    // Add links between nearby nodes
    let j = 0;
    while j < num_nodes {
        let k = j + 1;
        while k < num_nodes && k < j + 3 {
            let distance = calculate_node_distance(j, k, network_size);
            network = add_quantum_link(network, j, k, distance);
            k = k + 1;
        }
        j = j + 1;
    }

    return network;
}

pub fn run_quantum_protocol(protocol: string, state: QuantumState) -> any {
    if protocol == "teleportation" {
        return run_teleportation_protocol(state);
    } else if protocol == "superdense_coding" {
        return run_superdense_coding_protocol(state);
    } else if protocol == "bb84" {
        return run_bb84_protocol(state);
    } else if protocol == "grover" {
        return run_grover_protocol(state);
    } else {
        return null;
    }
}

fn run_teleportation_protocol(state: QuantumState) -> QuantumTeleportation {
    // Bell pair creation
    let bell_pair = array();
    push(bell_pair, at(state.qubits, 0));
    push(bell_pair, at(state.qubits, 1));

    // Alice's measurement
    let message_bits = quantum_teleportation_encode(at(state.qubits, 2), bell_pair);

    // Bob's correction
    let result = quantum_teleportation_decode(message_bits, bell_pair);

    return result;
}

fn run_superdense_coding_protocol(state: QuantumState) -> SuperDenseCoding {
    // Prepare message
    let message = array();
    push(message, 1);
    push(message, 0);

    // Encode
    let encoding = super_dense_coding_encode(message);

    // Decode
    encoding = super_dense_coding_decode(encoding);

    return encoding;
}

fn run_bb84_protocol(state: QuantumState) -> BB84KeyExchange {
    let exchange = initialize_bb84_exchange(100);

    // Alice sends qubits
    let qubits = alice_send_bb84_qubits(exchange);

    // Bob measures
    exchange = bob_measure_bb84_qubits(exchange, qubits);

    // Sift key
    exchange = sift_bb84_key(exchange);

    // Check for eavesdropping
    let qber = check_bb84_eavesdropping(exchange);

    return exchange;
}

fn run_grover_protocol(state: QuantumState) -> AlgorithmResult {
    let result = grover_algorithm(3, 5);
    return result;
}

pub fn compute_network_statistics(network: QuantumNetworkState) -> any {
    let stats = dict_create_stats();

    // Average fidelity
    let total_fidelity = 0.0;
    let i = 0;
    while i < length(network.links) {
        let link = at(network.links, i);
        total_fidelity = total_fidelity + link.fidelity;
        i = i + 1;
    }

    let avg_fidelity = if length(network.links) > 0 {
        total_fidelity / to_f64(length(network.links))
    } else {
        0.0
    };

    // Path metrics
    let num_nodes = length(network.nodes);
    let num_links = length(network.links);

    stats = dict_set(stats, "num_nodes", num_nodes);
    stats = dict_set(stats, "num_links", num_links);
    stats = dict_set(stats, "avg_fidelity", avg_fidelity);
    stats = dict_set(stats, "total_qubits", num_nodes * 100);

    return stats;
}

