fn calculate_node_distance(node1: i32, node2: i32, scale: i32) -> f64 {
    let dx = to_f64((node2 - node1) * 10);
    let dy = to_f64(((node2 % 5) - (node1 % 5)) * 20);

    let dist_sq = dx * dx + dy * dy;
    return sqrt_approx(dist_sq);
}

fn sqrt_approx(x: f64) -> f64 {
    if x < 0.0 { return 0.0; }
    if x == 0.0 { return 0.0; }

    let approx = x / 2.0;
    let i = 0;
    while i < 10 {
        approx = (approx + x / approx) / 2.0;
        i = i + 1;
    }
    return approx;
}

fn to_f64(x: i32) -> f64 {
    let result = 0.0;
    let i = 0;
    while i < x {
        result = result + 1.0;
        i = i + 1;
    }
    return result;
}

